def separate_paren_groups(paren_string: str) -> List[str]:
    stack = []
    current_group = ""
    groups = []

    for char in paren_string:
        if char == "(":
            stack.append(char)
            current_group += char
        elif char == ")":
            stack.pop()
            current_group += char
            if not stack:
                groups.append(current_group[1:-1])
                current_group = ""

    if stack:
        raise ValueError("Unbalanced parentheses")
    return groups

