def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for deg, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        term = ''
        if coeff != 1 or deg > 0:
            term += str(abs(coeff))
        if deg > 0:
            term += 'x^' + str(n - deg)
        else:
            term += 'x'
        terms.append(term)
        if coeff < 0:
            terms.append('-')
        if coeffs.index(coeff) < len(coeffs) - 1:
            terms.append('+')
    return ''.join(terms)

